package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class BackchannelLogoutUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property backchannel logout uri of oauth client ")
  void test_backchannel_logout_uri_v_o_builder() {
    Assertions.assertFalse(BackchannelLogoutUriVO.nullValue().getBackchannelLogoutUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        BackchannelLogoutUriVO.tryFrom(null).getBackchannelLogoutUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        BackchannelLogoutUriVO.from("one").getBackchannelLogoutUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> BackchannelLogoutUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", BackchannelLogoutUriVO.from("one").toString());
  }
}
